// src/lib/mcp/tools/list-blog-posts.ts
var list_blog_posts_default = defineTool3({
  name: "list_blog_posts",
  title: "List blog posts",
  description: "List all published Crux Consulting blog posts with title, summary, category, date and URL.",
  inputSchema: {
    language: z2.enum(["en", "de"]).nullable().describe("Language of the returned content. Defaults to English.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ language }) => {
    const lang = resolveLanguage(language);
    const posts = [...blogPosts].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map((post) => ({
      slug: post.slug,
      title: post.title[lang],
      summary: post.summary[lang],
      category: post.category,
      date: post.date,
      author: post.author,
      url: blogUrl(lang, post.slug)
    }));
    return {
      content: [
        {
          type: "text",
          text: posts.map((p) => `${p.title}
${p.category} \xB7 ${p.date} \xB7 ${p.author}
${p.summary}
${p.url}`).join("\n\n")
        }
      ],
      structuredContent: { language: lang, posts }
    };
  }
});

// src/lib/mcp/tools/get-blog-post.ts
import { defineTool as defineTool4, ToolError as ToolError2 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z3 } from "npm:zod@^4";
var get_blog_post_default = defineTool4({
  name: "get_blog_post",
  title: "Get blog post",
  description: "Get the full text of one Crux Consulting blog post by its slug (see list_blog_posts).",
  inputSchema: {
    slug: z3.string().min(1).describe("Blog post slug, e.g. 'why-AI-projects-fail'."),
    language: z3.enum(["en", "de"]).nullable().describe("Language of the returned content. Defaults to English.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug, language }) => {
    const lang = resolveLanguage(language);
    const needle = slug.trim().toLowerCase();
    const post = blogPosts.find((p) => p.slug.toLowerCase() === needle);
    if (!post) {
      throw new ToolError2(
        `No blog post with slug "${slug}". Use list_blog_posts to see available slugs.`
      );
    }
    const body = htmlToPlainText(post.content[lang]);
    return {
      content: [
        {
          type: "text",
          text: `${post.title[lang]}
${post.category} \xB7 ${post.date} \xB7 ${post.author}
${blogUrl(lang, post.slug)}

${body}`
        }
      ],
      structuredContent: {
        slug: post.slug,
        language: lang,
        title: post.title[lang],
        summary: post.summary[lang],
        category: post.category,
        date: post.date,
        author: post.author,
        url: blogUrl(lang, post.slug),
        content: body
      }
    };
  }
});

// src/lib/mcp/tools/search-content.ts
import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z4 } from "npm:zod@^4";
var search_content_default = defineTool5({
  name: "search_content",
  title: "Search site content",
  description: "Full-text search across Crux Consulting's public services and blog posts. Returns matching items with URLs and short excerpts.",
  inputSchema: {
    query: z4.string().min(2).describe("Search terms, e.g. 'tender automation'."),
    language: z4.enum(["en", "de"]).nullable().describe("Language of the returned content. Defaults to English.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, language }) => {
    const lang = resolveLanguage(language);
    const q = query.trim().toLowerCase();
    const serviceHits = services.filter(
      (s) => `${s.name} ${s.description} ${s.highlights.join(" ")}`.toLowerCase().includes(q)
    ).map((s) => ({ type: "service", title: s.name, url: s.url, excerpt: s.description }));
    const blogHits = blogPosts.map((post) => ({ post, body: htmlToPlainText(post.content[lang]) })).filter(
      ({ post, body }) => `${post.title[lang]} ${post.summary[lang]} ${body}`.toLowerCase().includes(q)
    ).map(({ post, body }) => {
      const idx = body.toLowerCase().indexOf(q);
      const excerpt = idx >= 0 ? body.slice(Math.max(0, idx - 120), idx + 240).trim() : post.summary[lang];
      return {
        type: "blog_post",
        title: post.title[lang],
        url: blogUrl(lang, post.slug),
        excerpt
      };
    });
    const results = [...serviceHits, ...blogHits];
    return {
      content: [
        {
          type: "text",
          text: results.length ? results.map((r) => `[${r.type}] ${r.title}
${r.url}
${r.excerpt}`).join("\n\n") : `No matches for "${query}".`
        }
      ],
      structuredContent: { query, language: lang, results }
    };
  }
});

